//! Generated source files, which nobody can fix at the source.
//!
//! holds-until: a generator's header takes a form the two below miss; then the
//! form is added here with its fixture, never a looser test.

const HEADER_LINES: usize = 15;

/// What a generator's own sentence starts with, before `DO NOT EDIT`
/// (Go's `Code generated by … DO NOT EDIT.`, protoc's `Generated by the
/// protocol buffer compiler. DO NOT EDIT!`). Anchored at the start of the
/// comment, so a hand-written comment that merely discusses the marker is
/// not one.
const SENTENCE_STARTS: [&str; 6] = [
    "code generated",
    "generated by",
    "generated file",
    "this file is generated",
    "auto-generated",
    "automatically generated",
];

/// The text of a comment line without its opener, lowercased; `None` when the
/// line is not a comment.
fn comment_text(line: &str) -> Option<String> {
    let trimmed = line.trim_start();
    ["//", "#", "/*", "*"]
        .iter()
        .find_map(|opener| trimmed.strip_prefix(opener))
        .map(|rest| {
            rest.trim_start_matches(['/', '!', '*', '#', ' ', '\t'])
                .to_lowercase()
        })
}

/// `@generated` standing alone as a word: not inside backticks or quotes, and
/// not part of a longer name.
fn has_generated_tag(text: &str) -> bool {
    text.match_indices("@generated").any(|(at, tag)| {
        let before = text[..at].chars().next_back();
        let after = text[at + tag.len()..].chars().next();
        before.is_none_or(|c| c.is_whitespace() || matches!(c, '/' | '*' | '#' | '(' | ':'))
            && after.is_none_or(|c| !c.is_alphanumeric() && c != '_' && c != '`')
    })
}

/// True when, among the first 15 lines, a comment carries the `@generated`
/// tag, or starts with a generator's sentence and says `DO NOT EDIT`.
pub(crate) fn is_generated(text: &str) -> bool {
    text.lines()
        .take(HEADER_LINES)
        .filter_map(comment_text)
        .any(|comment| {
            has_generated_tag(&comment)
                || (comment.contains("do not edit")
                    && SENTENCE_STARTS
                        .iter()
                        .any(|start| comment.starts_with(start)))
        })
}

#[cfg(test)]
mod tests {
    use super::is_generated;

    #[test]
    fn a_mockgen_header_marks_a_go_file() {
        assert!(is_generated(
            "// Code generated by MockGen. DO NOT EDIT.\npackage m\n"
        ));
    }

    #[test]
    fn a_prost_header_marks_a_rust_file() {
        assert!(is_generated("// This file is @generated by prost-build.\n"));
    }

    #[test]
    fn a_protoc_python_header_marks_a_python_file() {
        assert!(is_generated(
            "# Generated by the protocol buffer compiler.  DO NOT EDIT!\n"
        ));
    }

    #[test]
    fn a_protoc_gen_es_header_marks_a_ts_file() {
        assert!(is_generated("// @generated by protoc-gen-es\n"));
        assert!(is_generated("/** @generated */\n"));
    }

    #[test]
    fn a_doc_comment_mentioning_generated_alone_is_hand_written() {
        assert!(!is_generated(
            "/// Parses the generated output.\nfn f() {}\n"
        ));
    }

    #[test]
    fn a_comment_that_discusses_the_markers_is_hand_written() {
        assert!(!is_generated("// Files saying `@generated` are skipped.\n"));
        assert!(!is_generated("// A \"@generated\" line marks them.\n"));
        assert!(!is_generated(
            "// Both generated and DO NOT EDIT must appear.\n"
        ));
        assert!(!is_generated("// not@generated here\n"));
    }

    #[test]
    fn this_module_is_not_generated() {
        assert!(!is_generated(include_str!("generated.rs")));
    }

    #[test]
    fn a_marker_after_line_fifteen_is_ignored() {
        let mut text = "// header\n".repeat(15);
        text.push_str("// @generated\n");
        assert!(!is_generated(&text));
        let mut inside = "// header\n".repeat(14);
        inside.push_str("// @generated\n");
        assert!(is_generated(&inside));
    }

    #[test]
    fn a_marker_in_a_string_literal_is_ignored() {
        assert!(!is_generated("let s = \"// @generated\";\n"));
    }
}
